package com.corecs.solid.parser;
import com.corecs.solid.model.*;import com.github.javaparser.*;import com.github.javaparser.ast.*;import com.github.javaparser.ast.body.*;import com.github.javaparser.ast.expr.*;import org.springframework.stereotype.Component;import java.util.*;
@Component public class JavaAstParser {
 public List<ClassInfo> parse(String code){try{CompilationUnit cu=StaticJavaParser.parse(code);List<ClassInfo> out=new ArrayList<>();cu.findAll(ClassOrInterfaceDeclaration.class).forEach(c->{List<String> methods=c.getMethods().stream().map(MethodDeclaration::getNameAsString).toList();List<String> fields=c.getFields().stream().flatMap(f->f.getVariables().stream().map(v->v.getNameAsString()+":"+f.getElementType().asString())).toList();List<String> deps=new ArrayList<>();c.findAll(ObjectCreationExpr.class).forEach(x->deps.add(x.getType().asString()));c.getFields().forEach(f->deps.add(f.getElementType().asString()));c.getMethods().forEach(m->m.getParameters().forEach(p->deps.add(p.getType().asString())));List<String> interfaces=c.getImplementedTypes().stream().map(Object::toString).toList();String parent=c.getExtendedTypes().isEmpty()?null:c.getExtendedTypes().get(0).asString();List<String> overridden=c.getMethods().stream().filter(m->m.getAnnotationByName("Override").isPresent()).map(MethodDeclaration::getNameAsString).toList();int switchStatements=c.findAll(com.github.javaparser.ast.stmt.SwitchStmt.class).size();out.add(new ClassInfo(c.getNameAsString(),parent,c.isInterface(),methods,fields,deps.stream().distinct().filter(d->!d.equals(c.getNameAsString())).toList(),interfaces,overridden,switchStatements));});return out;}catch(ParseProblemException e){throw new IllegalArgumentException("Java parsing failed: "+e.getMessage());}}
}
